<div class="mb-4"><h1 class="h3 mb-1">Cari File</h1><p class="text-secondary mb-0">Cari nama file dan folder di seluruh Drive Anda.</p></div>
<form method="get" action="/search" class="d-flex gap-2 mb-4"><input class="form-control" name="q" value="<?= esc($term) ?>" placeholder="Masukkan nama file atau folder..." autofocus><button class="btn btn-primary">Cari</button></form>
<?php if ($term !== ''): ?><div class="card p-3 mb-3"><h2 class="h5">Folder (<?= count($folders) ?>)</h2><?php foreach ($folders as $folder): ?><div class="py-2 border-bottom"><a href="/files?folder=<?= (int)$folder['id'] ?>">📁 <?= esc($folder['name']) ?></a></div><?php endforeach ?><?php if (!$folders): ?><p class="text-secondary mb-0">Tidak ada folder yang cocok.</p><?php endif ?></div>
<div class="card p-3"><h2 class="h5">File (<?= count($files) ?>)</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nama</th><th>Tipe</th><th>Ukuran</th><th>Aksi</th></tr></thead><tbody><?php foreach ($files as $f): ?><tr><td><?= esc($f['original_name']) ?></td><td><?= esc($f['mime_type']) ?></td><td><?= number_format($f['size_bytes']/1048576,2) ?> MB</td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="/files/preview/<?= (int)$f['id'] ?>" target="_blank">Preview</a> <a class="btn btn-sm btn-outline-secondary" href="/files/download/<?= (int)$f['id'] ?>">Unduh</a></td></tr><?php endforeach ?><?php if (!$files): ?><tr><td colspan="4" class="text-center text-secondary">Tidak ada file yang cocok.</td></tr><?php endif ?></tbody></table></div></div><?php endif ?>
